CREATE FUNCTION public.can_write_factory(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _uid IS NOT NULL AND _uid=auth.uid() AND EXISTS(SELECT 1 FROM public.profiles WHERE auth_user_id=_uid AND is_active) AND EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_uid AND role::text=ANY(ARRAY['factory_floor_supervisor','senior_factory_supervisor','production_head','head_operations','managing_director','finance_director','sales_director','architecture_director','super_admin'])) $$;
CREATE FUNCTION public.can_view_factory_cost(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _uid IS NOT NULL AND _uid=auth.uid() AND EXISTS(SELECT 1 FROM public.profiles WHERE auth_user_id=_uid AND is_active) AND (public.can_view_running_bill(_uid) OR EXISTS(SELECT 1 FROM public.user_roles WHERE user_id=_uid AND role::text IN('production_head','head_operations'))) $$;
CREATE FUNCTION public.can_read_factory(_uid uuid) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT _uid IS NOT NULL AND _uid=auth.uid() AND (public.can_write_factory(_uid) OR public.can_view_running_bill(_uid)) $$;
REVOKE ALL ON FUNCTION public.can_write_factory(uuid),public.can_view_factory_cost(uuid),public.can_read_factory(uuid) FROM PUBLIC,anon;
GRANT EXECUTE ON FUNCTION public.can_write_factory(uuid),public.can_view_factory_cost(uuid),public.can_read_factory(uuid) TO authenticated,service_role;

