CREATE TABLE public.boq_work_location_log(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),boq_item_id uuid NOT NULL REFERENCES public.project_boq_items(id),old_location text NOT NULL,new_location text NOT NULL,created_by uuid NOT NULL DEFAULT auth.uid(),updated_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),is_archived boolean NOT NULL DEFAULT false);
GRANT SELECT ON public.boq_work_location_log TO authenticated; GRANT ALL ON public.boq_work_location_log TO service_role;
ALTER TABLE public.boq_work_location_log ENABLE ROW LEVEL SECURITY;
CREATE POLICY boq_location_log_read ON public.boq_work_location_log FOR SELECT TO authenticated USING(public.can_view_running_bill(auth.uid()));
