CREATE TABLE public.factory_labour_attendance(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),work_date date NOT NULL,worker_id uuid NOT NULL REFERENCES public.labour_workers(id),hours numeric NOT NULL CHECK(hours>=0 AND hours<=16),hours_confirmed boolean NOT NULL DEFAULT false,effective_hourly_rate numeric NOT NULL DEFAULT 0,amount numeric NOT NULL DEFAULT 0,no_photo_exception boolean NOT NULL DEFAULT false,is_archived boolean NOT NULL DEFAULT false,created_by uuid NOT NULL DEFAULT auth.uid(),updated_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),UNIQUE(work_date,worker_id));
GRANT SELECT(id,work_date,worker_id,hours,hours_confirmed,no_photo_exception,is_archived,created_by,updated_by,created_at,updated_at) ON public.factory_labour_attendance TO authenticated; GRANT ALL ON public.factory_labour_attendance TO service_role;
ALTER TABLE public.factory_labour_attendance ENABLE ROW LEVEL SECURITY;
CREATE POLICY factory_attendance_read ON public.factory_labour_attendance FOR SELECT TO authenticated USING(public.can_read_factory(auth.uid()));
CREATE TABLE public.factory_attendance_photos(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),work_date date NOT NULL,storage_path text NOT NULL UNIQUE,captured_at timestamptz NOT NULL,received_at timestamptz NOT NULL DEFAULT now(),gps_lat numeric NOT NULL,gps_lng numeric NOT NULL,gps_accuracy_m numeric NOT NULL,flags jsonb NOT NULL DEFAULT '{}'::jsonb,is_archived boolean NOT NULL DEFAULT false,created_by uuid NOT NULL DEFAULT auth.uid(),updated_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.factory_attendance_photos TO authenticated; GRANT ALL ON public.factory_attendance_photos TO service_role;
