CREATE TABLE public.factory_report_task_workers(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),report_id uuid NOT NULL,module_id uuid NOT NULL,stage text NOT NULL,worker_id uuid NOT NULL REFERENCES public.labour_workers(id),hours numeric NOT NULL CHECK(hours>=0.5 AND hours<=16),is_archived boolean NOT NULL DEFAULT false,created_by uuid NOT NULL DEFAULT auth.uid(),updated_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(report_id,module_id,stage) REFERENCES public.factory_report_blocks(report_id,module_id,stage),UNIQUE(report_id,module_id,stage,worker_id));
GRANT SELECT ON public.factory_report_task_workers TO authenticated; GRANT ALL ON public.factory_report_task_workers TO service_role;
ALTER TABLE public.factory_report_task_workers ENABLE ROW LEVEL SECURITY;
