CREATE TABLE public.factory_report_quantities(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),report_id uuid NOT NULL,module_id uuid NOT NULL,stage text NOT NULL,boq_item_id uuid NOT NULL REFERENCES public.project_boq_items(id),contractor_id uuid REFERENCES public.labour_contractors(id),rate_id uuid REFERENCES public.subcontract_rates(id),unit text,today_qty numeric NOT NULL CHECK(today_qty>=0 AND today_qty<>'NaN'::numeric),rate_used numeric,amount_inr numeric,remarks text,is_archived boolean NOT NULL DEFAULT false,created_by uuid NOT NULL DEFAULT auth.uid(),updated_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now(),FOREIGN KEY(report_id,module_id,stage) REFERENCES public.factory_report_blocks(report_id,module_id,stage),UNIQUE NULLS NOT DISTINCT(report_id,module_id,stage,boq_item_id,contractor_id));
GRANT SELECT(id,report_id,module_id,stage,boq_item_id,contractor_id,unit,today_qty,remarks,is_archived,created_by,updated_by,created_at,updated_at) ON public.factory_report_quantities TO authenticated; GRANT ALL ON public.factory_report_quantities TO service_role;
ALTER TABLE public.factory_report_quantities ENABLE ROW LEVEL SECURITY;
CREATE POLICY factory_quantities_read ON public.factory_report_quantities FOR SELECT TO authenticated USING(public.can_read_factory(auth.uid()));
CREATE TABLE public.factory_report_expenses(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),report_id uuid NOT NULL REFERENCES public.factory_daily_reports(id),module_id uuid REFERENCES public.modules(id),kind text NOT NULL CHECK(kind IN('consumable','expense')),description text NOT NULL CHECK(length(btrim(description))>0),amount_inr numeric NOT NULL CHECK(amount_inr>=0 AND amount_inr<>'NaN'::numeric),is_archived boolean NOT NULL DEFAULT false,created_by uuid NOT NULL DEFAULT auth.uid(),updated_by uuid NOT NULL DEFAULT auth.uid(),created_at timestamptz NOT NULL DEFAULT now(),updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.factory_report_expenses TO authenticated; GRANT ALL ON public.factory_report_expenses TO service_role;
