ALTER TABLE public.daily_production_logs ADD COLUMN factory_block_id uuid REFERENCES public.factory_report_blocks(id);
CREATE UNIQUE INDEX production_factory_block ON public.daily_production_logs(factory_block_id);
CREATE INDEX factory_workers_date_lookup ON public.factory_labour_attendance(work_date,worker_id);
CREATE INDEX factory_quantities_item_lookup ON public.factory_report_quantities(boq_item_id,report_id);
CREATE POLICY factory_photo_upload ON storage.objects FOR INSERT TO authenticated WITH CHECK(bucket_id='attendance-photos' AND public.can_write_factory(auth.uid()) AND ((split_part(name,'/',1)='factory-attendance' AND split_part(name,'/',2)=public.ist_today()::text) OR (split_part(name,'/',1)='factory-report' AND split_part(name,'/',2) BETWEEN (public.ist_today()-2)::text AND public.ist_today()::text)));
CREATE POLICY factory_photo_read ON storage.objects FOR SELECT TO authenticated USING(bucket_id='attendance-photos' AND split_part(name,'/',1) IN('factory-attendance','factory-report') AND public.can_read_factory(auth.uid()));

CREATE FUNCTION public._factory_window(p_date date) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_write_factory(auth.uid()) THEN RAISE EXCEPTION 'Factory reporting is not available for your role' USING ERRCODE='42501'; END IF; IF p_date IS NULL OR p_date NOT BETWEEN public.ist_today()-2 AND public.ist_today() THEN RAISE EXCEPTION 'Choose today or one of the previous two days'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('factory:'||p_date::text,0)); END $$;
CREATE FUNCTION public.add_factory_attendance_photo(p_storage_path text,p_captured_at timestamptz,p_lat numeric,p_lng numeric,p_accuracy_m numeric) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE v_id uuid; BEGIN PERFORM public._factory_window(public.ist_today()); IF p_storage_path IS NULL OR p_storage_path !~ ('^factory-attendance/'||public.ist_today()::text||'/[0-9a-f-]{36}\.jpg$') THEN RAISE EXCEPTION 'Toolbox talk photos can only be added for today'; END IF; IF p_captured_at IS NULL OR abs(extract(epoch FROM now()-p_captured_at))>600 THEN RAISE EXCEPTION 'Photo time is more than 10 minutes from server time'; END IF; IF p_lat IS NULL OR p_lng IS NULL OR p_accuracy_m IS NULL OR p_lat NOT BETWEEN -90 AND 90 OR p_lng NOT BETWEEN -180 AND 180 OR p_accuracy_m NOT BETWEEN 0 AND 100 THEN RAISE EXCEPTION 'A GPS fix accurate to 100 m or better is required'; END IF; IF (SELECT count(*) FROM public.factory_attendance_photos WHERE work_date=public.ist_today() AND NOT is_archived)>=3 THEN RAISE EXCEPTION 'Up to 3 toolbox talk photos per day'; END IF; IF NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='attendance-photos' AND name=p_storage_path) THEN RAISE EXCEPTION 'Upload the camera photo first'; END IF; INSERT INTO public.factory_attendance_photos(work_date,storage_path,captured_at,gps_lat,gps_lng,gps_accuracy_m) VALUES(public.ist_today(),p_storage_path,p_captured_at,p_lat,p_lng,p_accuracy_m) RETURNING id INTO v_id; RETURN v_id; END $$;
CREATE FUNCTION public.get_factory_attendance(p_date date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF NOT public.can_read_factory(auth.uid()) THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF; RETURN jsonb_build_object('standard_hours',public.get_labour_standard_hours(),'workers',COALESCE((SELECT jsonb_agg(jsonb_build_object('worker_id',w.id,'name',w.name,'skill_type',w.skill_type,'contractor_name',c.company_name,'worker_code',w.worker_code) ORDER BY w.name) FROM public.labour_workers w LEFT JOIN public.labour_contractors c ON c.id=w.contractor_id WHERE w.status='active'),'[]'::jsonb),'attendance',COALESCE((SELECT jsonb_agg(jsonb_build_object('worker_id',worker_id,'hours',hours,'hours_confirmed',hours_confirmed,'no_photo_exception',no_photo_exception)) FROM public.factory_labour_attendance WHERE work_date=p_date AND NOT is_archived),'[]'::jsonb),'photos',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',id,'storage_path',storage_path,'captured_at',captured_at,'flags',flags)) FROM public.factory_attendance_photos WHERE work_date=p_date AND NOT is_archived),'[]'::jsonb)); END $$;
CREATE FUNCTION public.save_factory_attendance(p_date date,p_rows jsonb,p_reason text DEFAULT NULL) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e jsonb; a public.factory_labour_attendance; h numeric; n integer:=0; exc boolean; rate numeric; BEGIN PERFORM public._factory_window(p_date); IF jsonb_typeof(p_rows) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Attendance needs a row list'; END IF; exc:=NOT EXISTS(SELECT 1 FROM public.factory_attendance_photos WHERE work_date=p_date AND NOT is_archived); IF exc AND (p_date=public.ist_today() OR NOT public.can_attendance_photo_exception(auth.uid()) OR length(btrim(coalesce(p_reason,'')))<10) THEN RAISE EXCEPTION 'Take the toolbox talk photo first.'; END IF; FOR e IN SELECT value FROM jsonb_array_elements(p_rows) LOOP IF NOT EXISTS(SELECT 1 FROM public.labour_workers WHERE id=(e->>'worker_id')::uuid AND status='active') THEN RAISE EXCEPTION 'Choose an active worker'; END IF; SELECT * INTO a FROM public.factory_labour_attendance WHERE work_date=p_date AND worker_id=(e->>'worker_id')::uuid FOR UPDATE; h:=CASE WHEN coalesce((e->>'present')::boolean,false) THEN CASE WHEN a.hours>0 THEN a.hours ELSE public.get_labour_standard_hours() END ELSE 0 END; IF a.id IS NOT NULL AND a.hours IS DISTINCT FROM h AND length(btrim(coalesce(p_reason,'')))<1 THEN RAISE EXCEPTION 'Add a reason for changing saved attendance'; END IF; IF EXISTS(SELECT 1 FROM public.factory_report_task_workers tw JOIN public.factory_daily_reports r ON r.id=tw.report_id WHERE r.report_date=p_date AND tw.worker_id=(e->>'worker_id')::uuid AND NOT tw.is_archived AND NOT r.is_archived GROUP BY tw.worker_id HAVING sum(tw.hours)>h) THEN RAISE EXCEPTION 'Allocated hours exceed the new attendance hours'; END IF; SELECT coalesce(hourly_rate,monthly_salary/208,0) INTO rate FROM public.labour_worker_compensation WHERE worker_id=(e->>'worker_id')::uuid; rate:=coalesce(a.effective_hourly_rate,rate,0); INSERT INTO public.factory_labour_attendance(work_date,worker_id,hours,effective_hourly_rate,amount,no_photo_exception) VALUES(p_date,(e->>'worker_id')::uuid,h,rate,h*rate,exc) ON CONFLICT(work_date,worker_id) DO UPDATE SET hours=excluded.hours,amount=excluded.amount,hours_confirmed=CASE WHEN factory_labour_attendance.hours IS NOT DISTINCT FROM excluded.hours THEN factory_labour_attendance.hours_confirmed ELSE false END,no_photo_exception=excluded.no_photo_exception,is_archived=false,updated_by=auth.uid(),updated_at=now(); INSERT INTO public.factory_report_edit_log(work_date,field,old_value,new_value,reason) VALUES(p_date,'attendance:'||(e->>'worker_id'),to_jsonb(a.hours),to_jsonb(h),p_reason); n:=n+1; END LOOP; RETURN n; END $$;
CREATE FUNCTION public.confirm_factory_hours(p_date date,p_rows jsonb) RETURNS integer LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE e jsonb; a public.factory_labour_attendance; h numeric; n integer:=0; BEGIN PERFORM public._factory_window(p_date); IF jsonb_typeof(p_rows) IS DISTINCT FROM 'array' THEN RAISE EXCEPTION 'Hours needs a row list'; END IF; FOR e IN SELECT value FROM jsonb_array_elements(p_rows) LOOP h:=(e->>'hours')::numeric; IF h IS NULL OR h NOT BETWEEN 0 AND 16 THEN RAISE EXCEPTION 'Hours must be between 0 and 16'; END IF; SELECT * INTO a FROM public.factory_labour_attendance WHERE work_date=p_date AND worker_id=(e->>'worker_id')::uuid AND hours>0 AND NOT is_archived FOR UPDATE; IF a.id IS NULL THEN RAISE EXCEPTION 'Worker is not marked present on this day'; END IF; IF EXISTS(SELECT 1 FROM public.factory_report_task_workers tw JOIN public.factory_daily_reports r ON r.id=tw.report_id WHERE r.report_date=p_date AND NOT r.is_archived AND NOT tw.is_archived AND tw.worker_id=a.worker_id GROUP BY tw.worker_id HAVING sum(tw.hours)>h) THEN RAISE EXCEPTION 'Allocated hours exceed the new attendance hours'; END IF; UPDATE public.factory_labour_attendance SET hours=h,amount=h*effective_hourly_rate,hours_confirmed=true,updated_by=auth.uid(),updated_at=now() WHERE id=a.id; INSERT INTO public.factory_report_edit_log(work_date,field,old_value,new_value,reason) VALUES(p_date,'confirmed_hours:'||a.worker_id,to_jsonb(a.hours),to_jsonb(h),'Evening hours confirmation'); n:=n+1; END LOOP; RETURN n; END $$;

CREATE FUNCTION public._factory_validate_workers(p_report uuid) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE d date; BEGIN IF NOT public.can_write_factory(auth.uid()) THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF; SELECT report_date INTO d FROM public.factory_daily_reports WHERE id=p_report; IF EXISTS(SELECT 1 FROM public.factory_report_task_workers tw LEFT JOIN public.factory_labour_attendance a ON a.work_date=d AND a.worker_id=tw.worker_id AND a.hours>0 AND NOT a.is_archived WHERE tw.report_id=p_report AND NOT tw.is_archived AND a.id IS NULL) THEN RAISE EXCEPTION 'Worker must be present in Factory on this date'; END IF; IF EXISTS(SELECT 1 FROM public.factory_report_task_workers tw JOIN public.factory_labour_attendance a ON a.work_date=d AND a.worker_id=tw.worker_id WHERE tw.report_id=p_report AND NOT tw.is_archived GROUP BY tw.worker_id,a.hours HAVING sum(tw.hours)>a.hours) THEN RAISE EXCEPTION 'Allocated hours exceed Factory attendance hours'; END IF; IF EXISTS(SELECT 1 FROM public.factory_report_task_workers tw WHERE tw.report_id=p_report AND NOT tw.is_archived AND NOT EXISTS(SELECT 1 FROM public.factory_report_blocks b WHERE b.report_id=tw.report_id AND b.module_id=tw.module_id AND b.stage=tw.stage AND NOT b.is_archived)) THEN RAISE EXCEPTION 'Worker allocation needs an active block'; END IF; END $$;
CREATE FUNCTION public.get_factory_report(p_date date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.factory_daily_reports; a jsonb; v jsonb; BEGIN IF NOT public.can_read_factory(auth.uid()) THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF; SELECT * INTO r FROM public.factory_daily_reports WHERE report_date=p_date AND NOT is_archived; a:=public.get_factory_attendance(p_date); v:=jsonb_build_object('report',CASE WHEN r.id IS NULL THEN NULL ELSE to_jsonb(r) END,'present_workers',COALESCE((SELECT jsonb_agg(jsonb_build_object('worker_id',w.id,'name',w.name,'skill_type',w.skill_type,'contractor_name',c.company_name,'attendance_hours',la.hours)) FROM public.factory_labour_attendance la JOIN public.labour_workers w ON w.id=la.worker_id LEFT JOIN public.labour_contractors c ON c.id=w.contractor_id WHERE la.work_date=p_date AND la.hours>0 AND NOT la.is_archived),'[]'::jsonb),'hours_unconfirmed',(SELECT count(*) FROM public.factory_labour_attendance WHERE work_date=p_date AND hours>0 AND NOT hours_confirmed AND NOT is_archived),'modules',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',m.id,'project_id',m.project_id,'name',m.name,'module_code',m.module_code,'current_stage',m.current_stage,'production_system',p.production_system,'project_name',p.name,'recent',EXISTS(SELECT 1 FROM public.daily_production_logs l WHERE l.module_id=m.id AND l.log_date=p_date-1),'last_logs',COALESCE((SELECT jsonb_agg(to_jsonb(z)) FROM(SELECT DISTINCT ON(stage_worked) stage_worked,stage_progress,log_date FROM public.daily_production_logs WHERE module_id=m.id AND log_date<=p_date ORDER BY stage_worked,log_date DESC,created_at DESC) z),'[]'::jsonb))) FROM public.modules m JOIN public.projects p ON p.id=m.project_id WHERE NOT coalesce(m.is_archived,false) AND NOT coalesce(p.is_archived,false)),'[]'::jsonb),'boq',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',b.id,'project_id',h.project_id,'sno',b.sno,'item_description',b.item_description,'unit',b.unit,'boq_qty',b.boq_qty,'so_far',COALESCE((SELECT sum(q.today_qty) FROM public.factory_report_quantities q JOIN public.factory_daily_reports f ON f.id=q.report_id WHERE q.boq_item_id=b.id AND f.status='submitted' AND NOT f.is_archived AND NOT q.is_archived AND f.id IS DISTINCT FROM r.id AND f.report_date<=p_date),0))) FROM public.project_boq_items b JOIN public.project_boq h ON h.id=b.boq_id WHERE b.work_location='factory' AND h.id=(SELECT id FROM public.project_boq WHERE project_id=h.project_id ORDER BY version_number DESC,uploaded_at DESC LIMIT 1)),'[]'::jsonb),'contractors',COALESCE((SELECT jsonb_agg(DISTINCT jsonb_build_object('contractor_id',c.id,'name',c.company_name,'project_id',s.project_id,'boq_item_id',s.boq_item_id)) FROM public.subcontract_rates s JOIN public.labour_contractors c ON c.id=s.contractor_id WHERE s.is_active),'[]'::jsonb),'blocks',COALESCE((SELECT jsonb_agg(to_jsonb(b)) FROM public.factory_report_blocks b WHERE report_id=r.id AND NOT is_archived),'[]'::jsonb),'task_workers',COALESCE((SELECT jsonb_agg(to_jsonb(t)) FROM public.factory_report_task_workers t WHERE report_id=r.id AND NOT is_archived),'[]'::jsonb),'quantities',COALESCE((SELECT jsonb_agg(jsonb_build_object('id',q.id,'module_id',q.module_id,'stage',q.stage,'boq_item_id',q.boq_item_id,'contractor_id',q.contractor_id,'unit',q.unit,'today_qty',q.today_qty,'remarks',q.remarks)) FROM public.factory_report_quantities q WHERE report_id=r.id AND NOT is_archived),'[]'::jsonb),'expenses',COALESCE((SELECT jsonb_agg(to_jsonb(e)) FROM public.factory_report_expenses e WHERE report_id=r.id AND NOT is_archived),'[]'::jsonb),'photos',COALESCE((SELECT jsonb_agg(to_jsonb(ph)) FROM public.factory_report_photos ph WHERE report_id=r.id AND NOT is_archived),'[]'::jsonb)); RETURN v; END $$;
CREATE FUNCTION public.save_factory_report_draft(p_date date,p_payload jsonb) RETURNS uuid LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.factory_daily_reports; e jsonb; m public.modules; b public.project_boq_items; h public.project_boq; q public.factory_report_quantities; v_rate public.subcontract_rates; bid uuid; cid uuid; mid uuid; st text; qty numeric; pct numeric; typ text; v_old jsonb; v_new jsonb; BEGIN PERFORM public._factory_window(p_date); IF jsonb_typeof(p_payload) IS DISTINCT FROM 'object' THEN RAISE EXCEPTION 'Report needs an object'; END IF; SELECT * INTO r FROM public.factory_daily_reports WHERE report_date=p_date FOR UPDATE; IF r.id IS NULL THEN INSERT INTO public.factory_daily_reports(report_date,notes) VALUES(p_date,p_payload->>'notes') RETURNING * INTO r; ELSE IF r.status='submitted' AND r.submitted_by IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Only the submitter can edit this report'; END IF; IF r.status='submitted' THEN v_old:=public.get_factory_report(p_date); END IF; UPDATE public.factory_daily_reports SET notes=CASE WHEN p_payload?'notes' THEN p_payload->>'notes' ELSE notes END,is_archived=false,updated_by=auth.uid(),updated_at=now() WHERE id=r.id; END IF;
IF p_payload?'blocks' THEN UPDATE public.factory_report_blocks SET is_archived=true,updated_by=auth.uid(),updated_at=now() WHERE report_id=r.id; FOR e IN SELECT value FROM jsonb_array_elements(p_payload->'blocks') LOOP mid:=(e->>'module_id')::uuid; st:=e->>'stage'; SELECT * INTO m FROM public.modules WHERE id=mid AND NOT coalesce(is_archived,false); IF m.id IS NULL THEN RAISE EXCEPTION 'Module not available'; END IF; SELECT production_system INTO typ FROM public.projects WHERE id=m.project_id; IF st IS NULL OR NOT(st=ANY(CASE typ WHEN 'hybrid' THEN ARRAY['Main Frame','Sub-Frame','Deck & Pour','Awaiting Panels','Panel Installation','MEP Inter-Panel','Waterproofing','Tiling & Cladding','Finishing','QC Inspection','Dispatch'] WHEN 'panelised' THEN ARRAY['LGSF Receipt','Frame Assembly','Moisture Barrier','Cera Board','MEP Rough-In','Pressure Test','Insulation','Habit Board','Window/Door','QC Sign-off'] ELSE ARRAY['Main Frame','Sub-Frame','MEP Rough-In','Insulation','Drywall','Paint','MEP Final','Windows & Doors','Finishing','QC Inspection','Dispatch'] END)) THEN RAISE EXCEPTION 'Stage does not belong to the module production system'; END IF; pct:=CASE WHEN e->>'stage_status'='completed' THEN 100 ELSE coalesce((e->>'progress_pct')::numeric,0) END; INSERT INTO public.factory_report_blocks(report_id,module_id,stage,stage_status,progress_pct,remarks) VALUES(r.id,mid,st,coalesce(e->>'stage_status','ongoing'),pct,e->>'remarks') ON CONFLICT(report_id,module_id,stage) DO UPDATE SET stage_status=excluded.stage_status,progress_pct=excluded.progress_pct,remarks=excluded.remarks,is_archived=false,updated_by=auth.uid(),updated_at=now(); END LOOP; END IF;
IF p_payload?'task_workers' THEN UPDATE public.factory_report_task_workers SET is_archived=true,updated_by=auth.uid(),updated_at=now() WHERE report_id=r.id; FOR e IN SELECT value FROM jsonb_array_elements(p_payload->'task_workers') LOOP INSERT INTO public.factory_report_task_workers(report_id,module_id,stage,worker_id,hours) VALUES(r.id,(e->>'module_id')::uuid,e->>'stage',(e->>'worker_id')::uuid,(e->>'hours')::numeric) ON CONFLICT(report_id,module_id,stage,worker_id) DO UPDATE SET hours=excluded.hours,is_archived=false,updated_by=auth.uid(),updated_at=now(); END LOOP; END IF; PERFORM public._factory_validate_workers(r.id);
IF p_payload?'quantities' THEN UPDATE public.factory_report_quantities SET is_archived=true,updated_by=auth.uid(),updated_at=now() WHERE report_id=r.id; FOR e IN SELECT value FROM jsonb_array_elements(p_payload->'quantities') LOOP mid:=(e->>'module_id')::uuid; st:=e->>'stage'; bid:=(e->>'boq_item_id')::uuid; cid:=nullif(e->>'contractor_id','')::uuid; qty:=coalesce((e->>'today_qty')::numeric,0); IF NOT EXISTS(SELECT 1 FROM public.factory_report_blocks WHERE report_id=r.id AND module_id=mid AND stage=st AND NOT is_archived) THEN RAISE EXCEPTION 'Quantity needs an active block'; END IF; SELECT * INTO m FROM public.modules WHERE id=mid; SELECT * INTO b FROM public.project_boq_items WHERE id=bid; SELECT * INTO h FROM public.project_boq WHERE id=b.boq_id; IF b.id IS NULL OR h.project_id IS DISTINCT FROM m.project_id THEN RAISE EXCEPTION 'BOQ item not in the module project'; END IF; IF b.work_location<>'factory' THEN RAISE EXCEPTION 'Site BOQ items can only be recorded in the Daily Site Report'; END IF; v_rate:=NULL; IF cid IS NOT NULL AND qty>0 THEN SELECT * INTO v_rate FROM public.subcontract_rates WHERE project_id=m.project_id AND contractor_id=cid AND boq_item_id=bid AND is_active; IF v_rate.id IS NULL THEN RAISE EXCEPTION 'No rate for this contractor on this item. Ask Planning to add it in Setup.'; END IF; END IF; INSERT INTO public.factory_report_quantities(report_id,module_id,stage,boq_item_id,contractor_id,unit,today_qty,remarks) VALUES(r.id,mid,st,bid,cid,b.unit,qty,e->>'remarks') ON CONFLICT(report_id,module_id,stage,boq_item_id,contractor_id) DO UPDATE SET today_qty=excluded.today_qty,remarks=excluded.remarks,is_archived=false,updated_by=auth.uid(),updated_at=now(); END LOOP; END IF;
IF p_payload?'expenses' THEN UPDATE public.factory_report_expenses SET is_archived=true,updated_by=auth.uid(),updated_at=now() WHERE report_id=r.id; FOR e IN SELECT value FROM jsonb_array_elements(p_payload->'expenses') LOOP mid:=nullif(e->>'module_id','')::uuid; IF mid IS NOT NULL AND NOT EXISTS(SELECT 1 FROM public.modules WHERE id=mid AND NOT coalesce(is_archived,false)) THEN RAISE EXCEPTION 'Expense module not available'; END IF; INSERT INTO public.factory_report_expenses(report_id,module_id,kind,description,amount_inr) VALUES(r.id,mid,e->>'kind',btrim(e->>'description'),(e->>'amount_inr')::numeric); END LOOP; END IF;
IF p_payload?'photos' THEN UPDATE public.factory_report_photos SET is_archived=true,updated_by=auth.uid(),updated_at=now() WHERE report_id=r.id; FOR e IN SELECT value FROM jsonb_array_elements(p_payload->'photos') LOOP IF e->>'storage_path' !~ ('^factory-report/'||p_date::text||'/[0-9a-f-]{36}\.jpg$') OR NOT EXISTS(SELECT 1 FROM storage.objects WHERE bucket_id='attendance-photos' AND name=e->>'storage_path') THEN RAISE EXCEPTION 'Upload a valid report photo first'; END IF; INSERT INTO public.factory_report_photos(report_id,storage_path) VALUES(r.id,e->>'storage_path') ON CONFLICT(report_id,storage_path) DO UPDATE SET is_archived=false,updated_by=auth.uid(),updated_at=now(); END LOOP; END IF;
IF r.status='submitted' THEN PERFORM public.submit_factory_report(r.id); v_new:=public.get_factory_report(p_date); INSERT INTO public.factory_report_edit_log(report_id,work_date,field,old_value,new_value,reason) VALUES(r.id,p_date,'submitted_report',v_old,v_new,'Post-submit correction'); END IF; RETURN r.id; END $$;
CREATE FUNCTION public.submit_factory_report(p_report_id uuid) RETURNS jsonb LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE r public.factory_daily_reports; b public.factory_report_blocks; q public.factory_report_quantities; s public.subcontract_rates; v_used numeric; v_rate numeric; n integer; BEGIN SELECT * INTO r FROM public.factory_daily_reports WHERE id=p_report_id AND NOT is_archived FOR UPDATE; IF r.id IS NULL THEN RAISE EXCEPTION 'Report not found'; END IF; PERFORM public._factory_window(r.report_date); IF r.status='submitted' AND r.submitted_by IS DISTINCT FROM auth.uid() THEN RAISE EXCEPTION 'Only the submitter can edit this report'; END IF; PERFORM public._factory_validate_workers(r.id); SELECT count(*) INTO n FROM public.factory_labour_attendance WHERE work_date=r.report_date AND hours>0 AND NOT hours_confirmed AND NOT is_archived; IF n>0 THEN RAISE EXCEPTION 'Confirm hours for % workers in Factory attendance.',n; END IF; IF NOT EXISTS(SELECT 1 FROM public.factory_report_blocks WHERE report_id=r.id AND NOT is_archived) AND length(btrim(coalesce(r.notes,'')))<5 THEN RAISE EXCEPTION 'Enter at least one block or a note of five characters'; END IF;
FOR q IN SELECT * FROM public.factory_report_quantities WHERE report_id=r.id AND NOT is_archived AND contractor_id IS NOT NULL AND today_qty>0 FOR UPDATE LOOP SELECT * INTO s FROM public.subcontract_rates WHERE contractor_id=q.contractor_id AND boq_item_id=q.boq_item_id AND is_active AND project_id=(SELECT project_id FROM public.modules WHERE id=q.module_id); IF s.id IS NULL THEN RAISE EXCEPTION 'No rate for this contractor on this item. Ask Planning to add it in Setup.'; END IF; PERFORM pg_advisory_xact_lock(hashtextextended('subcontract-rate:'||s.id::text,0)); IF s.rate_type='lump_sum' THEN SELECT coalesce(sum(q2.today_qty),0) INTO v_used FROM public.factory_report_quantities q2 JOIN public.factory_daily_reports r2 ON r2.id=q2.report_id WHERE q2.boq_item_id=q.boq_item_id AND q2.contractor_id=q.contractor_id AND NOT q2.is_archived AND NOT r2.is_archived AND (r2.status='submitted' OR r2.id=r.id); IF v_used>s.package_qty THEN RAISE EXCEPTION 'This takes the lump-sum package past its total'; END IF; END IF; v_rate:=coalesce(q.rate_used,CASE WHEN s.rate_type='per_unit' THEN s.rate_inr ELSE s.lump_sum_inr/s.package_qty END); UPDATE public.factory_report_quantities SET rate_id=coalesce(rate_id,s.id),rate_used=v_rate,amount_inr=today_qty*v_rate,updated_by=auth.uid(),updated_at=now() WHERE id=q.id; END LOOP;
FOR b IN SELECT * FROM public.factory_report_blocks WHERE report_id=r.id AND NOT is_archived LOOP INSERT INTO public.daily_production_logs(module_id,log_date,stage_worked,stage_progress,work_completed,submitted_by,factory_block_id) VALUES(b.module_id,r.report_date,b.stage,round(b.progress_pct)::integer,coalesce(b.remarks,''),auth.uid(),b.id) ON CONFLICT(factory_block_id) DO UPDATE SET stage_progress=excluded.stage_progress,work_completed=excluded.work_completed,updated_at=now(); END LOOP; INSERT INTO public.factory_report_edit_log(report_id,work_date,field,old_value,new_value,reason) VALUES(r.id,r.report_date,'status',to_jsonb(r.status),'"submitted"'::jsonb,'Report submitted'); UPDATE public.factory_daily_reports SET status='submitted',submitted_by=coalesce(submitted_by,auth.uid()),submitted_at=coalesce(submitted_at,now()),updated_by=auth.uid(),updated_at=now() WHERE id=r.id; RETURN jsonb_build_object('id',r.id,'status','submitted'); END $$;

CREATE FUNCTION public.get_boq_work_locations(p_project_id uuid) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ BEGIN IF auth.uid() IS NULL OR NOT public.can_view_running_bill(auth.uid()) THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF; RETURN coalesce((SELECT jsonb_agg(jsonb_build_object('id',b.id,'sno',b.sno,'item_description',b.item_description,'unit',b.unit,'work_location',b.work_location) ORDER BY b.sno) FROM public.project_boq_items b JOIN public.project_boq h ON h.id=b.boq_id WHERE h.project_id=p_project_id AND h.id=(SELECT id FROM public.project_boq WHERE project_id=p_project_id ORDER BY version_number DESC,uploaded_at DESC LIMIT 1)),'[]'::jsonb); END $$;
CREATE FUNCTION public.set_boq_work_location(p_item_id uuid,p_location text) RETURNS void LANGUAGE plpgsql SECURITY DEFINER SET search_path=public AS $$ DECLARE b public.project_boq_items; BEGIN IF auth.uid() IS NULL OR NOT public.can_view_running_bill(auth.uid()) THEN RAISE EXCEPTION 'Not authorized' USING ERRCODE='42501'; END IF; IF p_location IS NULL OR p_location NOT IN('site','factory') THEN RAISE EXCEPTION 'Choose Site or Factory'; END IF; SELECT * INTO b FROM public.project_boq_items WHERE id=p_item_id FOR UPDATE; IF b.id IS NULL THEN RAISE EXCEPTION 'BOQ item not found'; END IF; IF b.work_location=p_location THEN RETURN; END IF; IF p_location='factory' AND EXISTS(SELECT 1 FROM public.site_report_quantities WHERE boq_item_id=p_item_id AND today_qty>0) OR p_location='site' AND EXISTS(SELECT 1 FROM public.factory_report_quantities WHERE boq_item_id=p_item_id AND today_qty>0 AND NOT is_archived) THEN RAISE EXCEPTION 'This item already has quantities at its current location. Keep it there and split physical scope into another BOQ item.'; END IF; INSERT INTO public.boq_work_location_log(boq_item_id,old_location,new_location) VALUES(p_item_id,b.work_location,p_location); UPDATE public.project_boq_items SET work_location=p_location WHERE id=p_item_id; END $$;
CREATE FUNCTION public.get_factory_cost(p_from date,p_to date) RETURNS jsonb LANGUAGE plpgsql STABLE SECURITY DEFINER SET search_path=public AS $$ DECLARE v jsonb; BEGIN IF NOT public.can_view_factory_cost(auth.uid()) THEN RAISE EXCEPTION 'Not authorized to view Factory costs' USING ERRCODE='42501'; END IF; IF p_from IS NULL OR p_to IS NULL OR p_from>p_to THEN RAISE EXCEPTION 'Choose a valid date range'; END IF; WITH rpt AS(SELECT id,report_date FROM public.factory_daily_reports WHERE status='submitted' AND NOT is_archived AND report_date BETWEEN p_from AND p_to),workers AS(SELECT tw.module_id,tw.stage,tw.worker_id,w.name worker,sum(tw.hours) hours,sum(tw.hours*a.effective_hourly_rate) cost FROM public.factory_report_task_workers tw JOIN rpt r ON r.id=tw.report_id JOIN public.factory_labour_attendance a ON a.work_date=r.report_date AND a.worker_id=tw.worker_id JOIN public.labour_workers w ON w.id=tw.worker_id WHERE NOT tw.is_archived GROUP BY 1,2,3,4),lab AS(SELECT module_id,sum(hours) hours,sum(cost) cost FROM workers GROUP BY 1),exp AS(SELECT e.module_id,sum(e.amount_inr) FILTER(WHERE e.kind='consumable') consumables,sum(e.amount_inr) FILTER(WHERE e.kind='expense') expenses FROM public.factory_report_expenses e JOIN rpt r ON r.id=e.report_id WHERE NOT e.is_archived GROUP BY 1),boq AS(SELECT q.module_id,q.boq_item_id,b.sno,b.item_description,b.unit,b.boq_rate,sum(q.today_qty) qty,sum(q.today_qty*b.boq_rate) value FROM public.factory_report_quantities q JOIN rpt r ON r.id=q.report_id JOIN public.project_boq_items b ON b.id=q.boq_item_id WHERE NOT q.is_archived GROUP BY 1,2,3,4,5,6),val AS(SELECT module_id,sum(value) value FROM boq GROUP BY 1),subs AS(SELECT q.module_id,sum(q.amount_inr) amount FROM public.factory_report_quantities q JOIN rpt r ON r.id=q.report_id WHERE NOT q.is_archived AND q.contractor_id IS NOT NULL GROUP BY 1),ids AS(SELECT module_id FROM lab UNION SELECT module_id FROM exp WHERE module_id IS NOT NULL UNION SELECT module_id FROM val UNION SELECT module_id FROM public.factory_report_blocks WHERE report_id IN(SELECT id FROM rpt) AND NOT is_archived),mods AS(SELECT m.id module_id,m.project_id,m.module_code,m.name,coalesce(val.value,0) value_earned,coalesce(lab.hours,0) hours,coalesce(lab.cost,0) labour_cost,coalesce(exp.consumables,0) consumables,coalesce(exp.expenses,0) expenses,coalesce(subs.amount,0) subcontract_cost,coalesce(lab.cost,0)+coalesce(exp.consumables,0)+coalesce(exp.expenses,0)+coalesce(subs.amount,0) total_cost,coalesce(val.value,0)-coalesce(lab.cost,0)-coalesce(exp.consumables,0)-coalesce(exp.expenses,0)-coalesce(subs.amount,0) value_minus_cost FROM ids JOIN public.modules m ON m.id=ids.module_id LEFT JOIN lab ON lab.module_id=m.id LEFT JOIN exp ON exp.module_id=m.id LEFT JOIN val ON val.module_id=m.id LEFT JOIN subs ON subs.module_id=m.id),unalloc AS(SELECT sum(greatest(a.hours-coalesce(x.h,0),0)) hours,sum(greatest(a.hours-coalesce(x.h,0),0)*a.effective_hourly_rate) cost FROM public.factory_labour_attendance a LEFT JOIN(SELECT tw.worker_id,r.report_date,sum(tw.hours) h FROM public.factory_report_task_workers tw JOIN rpt r ON r.id=tw.report_id WHERE NOT tw.is_archived GROUP BY 1,2) x ON x.worker_id=a.worker_id AND x.report_date=a.work_date WHERE a.work_date IN(SELECT report_date FROM rpt) AND NOT a.is_archived),stages AS(SELECT module_id,stage,sum(hours) hours,sum(cost) labour_cost FROM workers GROUP BY 1,2) SELECT jsonb_build_object('modules',coalesce((SELECT jsonb_agg(to_jsonb(mods)) FROM mods),'[]'::jsonb),'boq',coalesce((SELECT jsonb_agg(to_jsonb(boq)) FROM boq),'[]'::jsonb),'stages',coalesce((SELECT jsonb_agg(to_jsonb(stages)) FROM stages),'[]'::jsonb),'workers',coalesce((SELECT jsonb_agg(to_jsonb(workers)) FROM workers),'[]'::jsonb),'unallocated',coalesce((SELECT to_jsonb(unalloc) FROM unalloc),'{}'::jsonb),'factory_level',coalesce((SELECT jsonb_build_object('consumables',coalesce(consumables,0),'expenses',coalesce(expenses,0)) FROM exp WHERE module_id IS NULL),'{"consumables":0,"expenses":0}'::jsonb),'attendance_total',coalesce((SELECT sum(amount) FROM public.factory_labour_attendance WHERE work_date IN(SELECT report_date FROM rpt) AND NOT is_archived),0)) INTO v; RETURN v; END $$;

DO $patch$ DECLARE d text; anchor text; BEGIN d:=pg_get_functiondef('public.save_site_report_draft(uuid,date,jsonb)'::regprocedure); anchor:='IF NOT FOUND THEN RAISE EXCEPTION ''BOQ line not in this project''; END IF;'; IF position(anchor IN d)=0 THEN RAISE EXCEPTION 'Site quantity validation anchor missing'; END IF; d:=replace(d,anchor,anchor||E'\n IF EXISTS(SELECT 1 FROM public.project_boq_items WHERE id=v_bid AND work_location=''factory'') THEN RAISE EXCEPTION ''Factory BOQ items can only be recorded in the Daily Factory Report''; END IF;'); EXECUTE d; END $patch$;
DO $patch$ DECLARE d text; a text; BEGIN d:=pg_get_functiondef('public.get_running_bill(uuid,date)'::regprocedure); a:='q AS (SELECT s.* FROM public.site_report_quantities s JOIN rpt ON rpt.id = s.report_id),'; IF position(a IN d)=0 THEN RAISE EXCEPTION 'Running Bill quantity anchor missing'; END IF; d:=replace(d,a,$q$q AS (SELECT s.boq_item_id,s.contractor_id,s.today_qty,s.rate_used,s.amount_inr,s.rate_id,s.extra_work_description,s.unit,'Site'::text source FROM public.site_report_quantities s JOIN rpt ON rpt.id=s.report_id UNION ALL SELECT f.boq_item_id,f.contractor_id,f.today_qty,f.rate_used,f.amount_inr,f.rate_id,NULL::text,f.unit,'Factory'::text FROM public.factory_report_quantities f JOIN public.factory_daily_reports fr ON fr.id=f.report_id JOIN public.modules m ON m.id=f.module_id WHERE m.project_id=p_project_id AND fr.status='submitted' AND NOT fr.is_archived AND NOT f.is_archived AND fr.report_date<=p_as_of),$q$); d:=replace(d,'sum(today_qty) FILTER (WHERE contractor_id IS NOT NULL) sub_qty','sum(today_qty) FILTER (WHERE contractor_id IS NOT NULL) sub_qty, sum(today_qty) FILTER(WHERE source=''Factory'') factory_qty'); d:=replace(d,'COALESCE(qa.sub_qty,0) sub_qty,','COALESCE(qa.sub_qty,0) sub_qty, COALESCE(qa.factory_qty,0) factory_qty,'); d:=replace(d,'SELECT c.company_name contractor,','SELECT q.source location,c.company_name contractor,'); d:=replace(d,'GROUP BY c.company_name, b.sno','GROUP BY q.source,c.company_name, b.sno'); d:=replace(d,'''subcontract'', COALESCE','''factory_labour'', COALESCE((SELECT jsonb_agg(to_jsonb(z)) FROM(SELECT m.id module_id,m.module_code,m.name,sum(tw.hours) hours,sum(tw.hours*a.effective_hourly_rate) amount FROM public.factory_report_task_workers tw JOIN public.factory_daily_reports fr ON fr.id=tw.report_id JOIN public.modules m ON m.id=tw.module_id JOIN public.factory_labour_attendance a ON a.worker_id=tw.worker_id AND a.work_date=fr.report_date WHERE m.project_id=p_project_id AND fr.status=''submitted'' AND NOT fr.is_archived AND NOT tw.is_archived AND fr.report_date<=p_as_of GROUP BY m.id,m.module_code,m.name) z),''[]''::jsonb), ''subcontract'', COALESCE'); d:=replace(d,'''own_labour_cost'', COALESCE','''factory_labour_cost'',COALESCE((SELECT sum(tw.hours*a.effective_hourly_rate) FROM public.factory_report_task_workers tw JOIN public.factory_daily_reports fr ON fr.id=tw.report_id JOIN public.modules m ON m.id=tw.module_id JOIN public.factory_labour_attendance a ON a.worker_id=tw.worker_id AND a.work_date=fr.report_date WHERE m.project_id=p_project_id AND fr.status=''submitted'' AND NOT fr.is_archived AND NOT tw.is_archived AND fr.report_date<=p_as_of),0), ''own_labour_cost'', COALESCE'); EXECUTE d; END $patch$;
DO $grants$ DECLARE p record; BEGIN FOR p IN SELECT oid::regprocedure signature,proname FROM pg_proc WHERE pronamespace='public'::regnamespace AND proname IN('_factory_window','_factory_validate_workers','add_factory_attendance_photo','get_factory_attendance','save_factory_attendance','confirm_factory_hours','get_factory_report','save_factory_report_draft','submit_factory_report','get_boq_work_locations','set_boq_work_location','get_factory_cost') LOOP EXECUTE format('REVOKE ALL ON FUNCTION %s FROM PUBLIC,anon,authenticated',p.signature); EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO service_role',p.signature); IF p.proname NOT LIKE '\_factory\_%' THEN EXECUTE format('GRANT EXECUTE ON FUNCTION %s TO authenticated',p.signature); END IF; END LOOP; END $grants$;